var KIND={bad:["b-bad","위반 의심 사례",""],after:["b-ok","조치 전·후","after"],ref:["b-info","시설·관찰 참고",""],dg:["b-teal","그림","dg"],anim:["b-info","움직이는 그림","anim"]};
function isDg(m){return m.kind==="dg"||m.kind==="anim";}
function mediaById(id){for(var i=0;i<MEDIA.length;i++){var m=MEDIA[i];if(m.id===id||(m.pair&&(m.pair[0]===id||m.pair[1]===id)))return m;}return null;}
function tile(m){
  var key=m.pair?m.pair[1]:m.id, inner, tag=KIND[m.kind];
  if(isDg(m)) inner=DG[m.id]+'<em class="'+KIND[m.kind][2]+'">'+(m.kind==="anim"?"움직이는 그림":"그림")+'</em>';
  else if(m.pair) inner='<img src="'+PH[m.pair[1]]+'" alt="" loading="lazy"><em class="after">조치 전·후</em>';
  else inner='<img src="'+PH[m.id]+'" alt="" loading="lazy">'+(m.kind==="bad"?'<em>위반 의심</em>':m.kind==="ref"?'<em class="dg">시설 참고</em>':'');
  return '<button type="button" class="mtile" data-m="'+key+'"><span class="ph">'+inner+'</span><span>'+esc(m.t)+'</span></button>';
}
function mediaBlock(list,title){ if(!list.length) return ""; return '<div class="media-h">'+(title||"사진·그림 예시")+' '+list.length+'</div><div class="media">'+list.map(tile).join("")+'</div>'; }
function bindTiles(root){root.querySelectorAll(".mtile").forEach(function(t){t.addEventListener("click",function(e){e.preventDefault();var m=mediaById(t.dataset.m);openLb(m,m.pair?"before":"");});});}

