/* ---------- 검색·즐겨찾기·조항 링크 ---------- */
var favorites=load("ms.favorites",[]);if(!Array.isArray(favorites))favorites=[];
var ENTRIES=[];
BYL14.forEach(function(s){var no=parseInt(s.title,10);s.items.forEach(function(text,i){var m=text.match(/^([가-힣])\.\s*([\s\S]*)$/);ENTRIES.push({id:"dust-"+no+"-"+(m?m[1]:i),route:"dust/"+no+"/"+(m?m[1]:i),title:s.title,basis:"시행규칙 별표 14 제"+no+"호"+(m?" "+m[1]+"목":""),text:m?m[2]:text});});});
AIRV.forEach(function(v){ENTRIES.push({id:"air-"+v.id,route:"air/"+v.id,title:v.n,basis:v.a,text:[v.txt,v.cond,v.mg,v.cr].filter(Boolean).join(" ")});});
function entryActions(id){var on=favorites.indexOf(id)>-1;return '<div class="entry-actions"><button class="btn sec" type="button" data-favorite="'+id+'" aria-pressed="'+on+'">'+(on?'즐겨찾기 해제':'즐겨찾기')+'</button><button class="btn sec" type="button" data-share="'+id+'">조항 링크 복사</button></div>';}
function renderSearch(){var q=$("lawSearch").value.trim().replace(/\s+/g,"").toLowerCase(),only=$("favoritesOnly").checked;
  var found=ENTRIES.filter(function(en){return (!only||favorites.indexOf(en.id)>-1)&&(!q||(en.title+en.basis+en.text).replace(/\s+/g,"").toLowerCase().indexOf(q)>-1);});
  $("searchCount").textContent=found.length+"개 조항";
  $("searchResults").innerHTML=found.length?found.map(function(en){return '<article class="search-result"><a class="result-link" href="#'+encodeURI(en.route)+'"><b>'+esc(en.title)+'</b><span class="basis">'+esc(en.basis)+'</span><p>'+esc(en.text)+'</p></a>'+entryActions(en.id)+'</article>';}).join(""):'<p class="small">'+(only?'저장한 즐겨찾기가 없습니다. 조항의 즐겨찾기 버튼으로 저장하세요.':'일치하는 조항이 없습니다. 작업명이나 시설명을 바꿔 검색하세요.')+'</p>';
}
document.addEventListener("click",function(e){var f=e.target.closest("[data-favorite]"),sh=e.target.closest("[data-share]");if(f){var id=f.dataset.favorite,k=favorites.indexOf(id);if(k>-1)favorites.splice(k,1);else favorites.push(id);save("ms.favorites",favorites);document.querySelectorAll('[data-favorite="'+id+'"]').forEach(function(b){var on=favorites.indexOf(id)>-1;b.setAttribute("aria-pressed",on);b.textContent=on?"즐겨찾기 해제":"즐겨찾기";});if($("favoritesOnly").checked)renderSearch();toast(k>-1?"즐겨찾기에서 지웠습니다":"즐겨찾기에 저장했습니다");}
  if(sh){var en=ENTRIES.find(function(x){return x.id===sh.dataset.share;});if(!en)return;var url=new URL(location.pathname,location.origin);url.hash=en.route;copyLink(url.href);}});
function copyLink(text){function fallback(){var t=document.createElement("textarea"),focus=document.activeElement;t.value=text;t.style.cssText="position:fixed;top:0;left:-9999px";document.body.appendChild(t);t.select();var ok=document.execCommand("copy");t.remove();if(focus)focus.focus();toast(ok?"조항 링크를 복사했습니다":"주소창의 링크를 복사하세요");}if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(text).then(function(){toast("조항 링크를 복사했습니다");},fallback);else fallback();}
$("lawSearch").addEventListener("input",renderSearch);$("favoritesOnly").addEventListener("change",renderSearch);
$("homeFavorites").addEventListener("click",function(){$("favoritesOnly").checked=true;$("lawSearch").value="";go("library");});
function route(){var parts;try{parts=decodeURIComponent(location.hash.slice(1)).split("/");}catch(e){parts=["home"];}
  var view=parts[0]||"home";go(view,true);var target=null;
  if(view==="dust"&&/^\d+$/.test(parts[1]||"")){selectSub("dustTabs","d-law");var d=$("dust-"+parts[1]);if(d){d.open=true;target=parts[2]?$("dust-"+parts[1]+"-"+parts[2]):d;}}
  if(view==="air"&&/^\d+$/.test(parts[1]||"")){selectSub("airTabs","a-law");target=$("air-"+parts[1]);if(target)target.open=true;}
  if(target){requestAnimationFrame(function(){target.scrollIntoView({block:"start"});target.tabIndex=-1;target.focus({preventScroll:true});});}
}

/* ---------- 공통 ---------- */
function $(id){return document.getElementById(id);}
function esc(s){return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];});}
function strip(h){return h.replace(/<[^>]+>/g,"");}
function load(k,d){try{var v=localStorage.getItem(k);return v?JSON.parse(v):d;}catch(e){return d;}}
var saveFailed=false;
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));saveFailed=false;return true;}catch(e){saveFailed=true;toast("기기에 저장하지 못했습니다. 보고문안은 복사하거나 내려받으세요.");return false;}}
function toast(m){var t=$("toast");t.textContent=m;t.classList.add("show");clearTimeout(t._h);t._h=setTimeout(function(){t.classList.remove("show");},1800);}
function blank(){var common={name:"",addr:"",time:nowLocal(),photoN:"",urgent:"",memo:"",draft:"",draftEdited:false};return {dust:Object.assign({},common,{sites:["build"],near:false,wind:"",marks:{},notes:{}}),air:Object.assign({},common,{marks:{},notes:{}})};}
var S=load("ms2.draft",null)||blank();
var defaults=blank();
["dust","air"].forEach(function(k){S[k]=Object.assign(defaults[k],S[k]||{});S[k].marks=S[k].marks||{};S[k].notes=S[k].notes||{};if(!S[k].time)S[k].time=nowLocal();});
if(!Array.isArray(S.dust.sites)||!S.dust.sites.length)S.dust.sites=["build"];

function persist(){save("ms2.draft",S);}
function dctx(){var w=AirKeeperCore.number(S.dust.wind);return {near:S.dust.near,wind:Number.isFinite(w)?w:null};}
