/* ---------- 화면 이동 ---------- */
var SUBTITLE={home:"미세먼지 민간점검단 업무지원",dust:"감시 1 · 비산먼지 억제조치",air:"감시 2 · 대기배출사업장",rep:"보고문안 초안",rules:"사업 개요 · 준수 사항",library:"기준 검색 · 즐겨찾기",offline:"오프라인 자료 · 앱 설치"};
function go(v,skipHash){
  if(!SUBTITLE[v])v="home";
  document.querySelectorAll("[data-view]").forEach(function(s){s.hidden=s.dataset.view!==v;});
  document.querySelectorAll(".tab").forEach(function(b){if(b.dataset.go===v)b.setAttribute("aria-current","page");else b.removeAttribute("aria-current");});
  $("backBtn").hidden=v==="home"; $("brandSub").textContent=SUBTITLE[v];
  if(v==="rep"){renderChips();renderReport();}
  if(v==="dust"){$("wind").value=S.dust.wind;$("nearHome").checked=S.dust.near;$("siteName").value=S.dust.name;renderSites();renderDust();}
  if(v==="air"){$("airName").value=S.air.name;renderAir();}
  if(v==="library")renderSearch();
  if(v==="offline")checkOffline();
  window.scrollTo(0,0); if(!skipHash&&location.hash!=="#"+v){try{history.pushState(null,"","#"+v);}catch(e){}}
}
document.addEventListener("click",function(e){var b=e.target.closest("[data-go]");if(b)go(b.dataset.go);});
$("backBtn").addEventListener("click",function(){go("home");});
function selectSub(id,sub){var root=$(id);root.querySelectorAll("button").forEach(function(x){var on=x.dataset.sub===sub;x.setAttribute("aria-selected",on);x.tabIndex=on?0:-1;$(x.dataset.sub).hidden=!on;});}
function subtabs(id){var root=$(id),bs=Array.from(root.querySelectorAll("button"));bs.forEach(function(b,i){var panel=$(b.dataset.sub);b.id="tab-"+b.dataset.sub;b.setAttribute("aria-controls",panel.id);panel.setAttribute("role","tabpanel");panel.setAttribute("aria-labelledby",b.id);b.tabIndex=b.getAttribute("aria-selected")==="true"?0:-1;
  b.addEventListener("click",function(){selectSub(id,b.dataset.sub);window.scrollTo(0,0);});
  b.addEventListener("keydown",function(e){var n;if(e.key==="ArrowRight")n=(i+1)%bs.length;else if(e.key==="ArrowLeft")n=(i+bs.length-1)%bs.length;else if(e.key==="Home")n=0;else if(e.key==="End")n=bs.length-1;else return;e.preventDefault();bs[n].click();bs[n].focus();});});}
subtabs("dustTabs");subtabs("airTabs");
var modalTrigger=null,activeModal=null;
function modalOpen(id,closeId){var modal=$(id);if(activeModal!==modal){modalTrigger=document.activeElement;activeModal=modal;document.querySelectorAll("body > header, body > main, body > nav").forEach(function(el){el.inert=true;});}modal.hidden=false;document.body.style.overflow="hidden";$(closeId).focus();}
function modalClose(id){if($(id).hidden)return;$(id).hidden=true;activeModal=null;document.body.style.overflow="";document.querySelectorAll("body > header, body > main, body > nav").forEach(function(el){el.inert=false;});if(modalTrigger&&modalTrigger.isConnected)modalTrigger.focus();modalTrigger=null;}
document.addEventListener("keydown",function(e){if(!activeModal||e.key!=="Tab")return;var fs=Array.from(activeModal.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),[tabindex="0"]')).filter(function(el){return el.getClientRects().length;});if(!fs.length){e.preventDefault();return;}var first=fs[0],last=fs[fs.length-1];if(e.shiftKey&&(document.activeElement===first||!activeModal.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!activeModal.contains(document.activeElement))){e.preventDefault();first.focus();}});

/* ---------- 확대 보기 ---------- */
function openLb(m,which){
  var h;
  if(isDg(m))h='<div class="dgwrap">'+DG[m.id]+'</div>';
  else if(m.pair)h='<img src="'+PH[which==="before"?m.pair[0]:m.pair[1]]+'" alt="">';
  else h='<img src="'+PH[m.id]+'" alt="'+esc(m.t)+'">';
  $("lbImg").innerHTML=h;
  var label=m.pair?(which==="before"?"조치 전":"조치 후"):KIND[m.kind][1];
  $("lbCap").innerHTML='<span class="badge '+KIND[m.kind][0]+'" style="align-self:flex-start">'+label+'</span><b>'+esc(m.t)+'</b><p>'+esc(m.d)+'</p>'+(m.clauses&&m.clauses.length?'<small>관련 조항: 별표 14 '+m.clauses.map(function(c){return esc('제'+c.split('-')[0]+'호 '+c.split('-')[1]+'목');}).join(' · ')+'</small>':'')+(m.originalCaption?'<small>원자료 분류 제목: '+esc(m.originalCaption)+'</small>':'')+'<small>출처: '+esc(m.src)+'</small>'+(m.pair?'<button class="lb-close" type="button" id="lbSwap" style="align-self:flex-start;margin-top:6px">'+(which==="before"?"조치 후 보기":"조치 전 보기")+'</button>':'');
  modalOpen("lb","lbClose");
  var sw=$("lbSwap");if(sw)sw.addEventListener("click",function(){openLb(m,which==="before"?"after":"before");});
}
function closeLb(){modalClose("lb");}
$("lbClose").addEventListener("click",closeLb);
$("lb").addEventListener("click",function(e){if(e.target===$("lb")||e.target===$("lbImg"))closeLb();});
document.addEventListener("keydown",function(e){if(e.key==="Escape")closeLb();});

/* ---------- 점검 공통 렌더 ---------- */
function itemHtml(it,st,ctx,extra){
  var m=st.marks[it.id]||"";
  var thumbs=(it.m||[]).map(function(id){return mediaById(id);}).filter(Boolean);
  return '<article class="item" data-id="'+it.id+'" data-st="'+m+'"><div><h3>'+it.t+'</h3><div class="basis">'+it.b+'</div></div>'+
   '<div class="std">'+it.std(ctx)+'</div>'+(extra||"")+
   (thumbs.length?'<div class="thumbs">'+thumbs.map(function(mm){var k=mm.pair?mm.pair[1]:mm.id;var inner=isDg(mm)?DG[mm.id]:'<img src="'+PH[k]+'" alt="" loading="lazy">';return '<button type="button" class="thumb mtile" data-m="'+k+'"><span class="ph">'+inner+'</span><span>'+esc(mm.t)+'</span></button>';}).join("")+'</div>':'')+
   '<details class="tip"><summary>확인 및 증거 확보 요령</summary><p>'+it.tip+'</p></details>'+
   '<div class="seg" role="group" aria-label="'+esc(it.t)+' 판정">'+['ok:적정','bad:위반 의심','na:확인 불가'].map(function(p){var a=p.split(":");return '<button type="button" data-v="'+a[0]+'" aria-pressed="'+(m===a[0])+'">'+a[1]+'</button>';}).join("")+'</div>'+
   (m==="bad"?'<textarea class="note" placeholder="관찰 내용 예: '+esc(it.hint)+'">'+esc(st.notes[it.id]||"")+'</textarea>':'')+'</article>';
}
function bindItems(root,st,rerender){
  root.querySelectorAll(".item").forEach(function(el){var id=el.dataset.id;
    el.querySelectorAll(".seg button").forEach(function(b){b.addEventListener("click",function(){st.marks[id]=st.marks[id]===b.dataset.v?"":b.dataset.v;persist();rerender();
      if(st.marks[id]==="bad"){var n=root.querySelector('.item[data-id="'+id+'"] .note');if(n)n.focus();}});});
    var n=el.querySelector(".note");if(n)n.addEventListener("input",function(){st.notes[id]=n.value;persist();});
  });
  bindTiles(root);
}
function progressHtml(list,st){var c={ok:0,bad:0,na:0};list.forEach(function(it){var m=st.marks[it.id];if(m)c[m]++;});var left=list.length-c.ok-c.bad-c.na;
  return '<span class="badge b-teal">'+list.length+'항목</span><span class="badge b-bad">위반 의심 '+c.bad+'</span><span class="badge b-ok">적정 '+c.ok+'</span><span class="badge b-na">확인 불가 '+c.na+'</span><span class="muted">'+(left?'남은 '+left:'완료')+'</span>';}

/* 감시 1 */
function dList(){return DITEMS.filter(function(it){return it.sites.some(function(s){return S.dust.sites.indexOf(s)>-1;});});}
function renderSites(){
  $("sites").innerHTML=SITES.map(function(s){return '<button type="button" class="chip" data-s="'+s.id+'" aria-pressed="'+(S.dust.sites.indexOf(s.id)>-1)+'">'+s.name+'</button>';}).join("");
  $("sites").querySelectorAll(".chip").forEach(function(b){b.addEventListener("click",function(){var a=S.dust.sites,i=a.indexOf(b.dataset.s);if(i>-1){if(a.length>1)a.splice(i,1);}else a.push(b.dataset.s);persist();renderSites();renderDust();});});
}
function renderDust(){
  var list=dList(),c=dctx(),html="",g="";
  list.forEach(function(it){if(it.g!==g){html+='<div class="sec-t">'+it.g+'</div>';g=it.g;}html+=itemHtml(it,S.dust,c);});
  $("dItems").innerHTML=html; bindItems($("dItems"),S.dust,renderDust); $("dProgress").innerHTML=progressHtml(list,S.dust);
}
$("nearHome").checked=S.dust.near;$("wind").value=S.dust.wind;$("siteName").value=S.dust.name;
$("nearHome").addEventListener("change",function(e){S.dust.near=e.target.checked;persist();renderDust();});
