/* 감시 2 */
function vioById(id){for(var i=0;i<AIRV.length;i++)if(AIRV[i].id===id)return AIRV[i];return null;}
function penTable(v){var t=v.tbl;return '<div class="pen">'+t.rows.map(function(r){var heads=t.headers.slice(1);var steps=r.slice(1).map(function(x,i){return [heads[i],x];}).filter(function(x){return x[1]&&x[1]!=="-";});
  return '<div class="pen-row"><div class="pen-l">'+esc(r[0])+'</div><div class="pen-s">'+steps.map(function(x,i){var hot=/허가취소|폐쇄|사용중지|조업정지/.test(x[1]);return (i?'<span class="pen-ar">→</span>':'')+'<span class="pen-st'+(hot?' hot':'')+'"><small>'+esc(x[0])+'</small>'+esc(x[1])+'</span>';}).join("")+'</div></div>';}).join("")+'</div>';}
function renderAir(){
  var html=AITEMS.map(function(it){var v=vioById(it.vio);
    var extra='<div class="signal"><b>외부 관찰 사항</b> · '+esc(it.sig)+'</div>'+
      (v?'<details class="tip"><summary>처분·벌칙 보기 ('+esc(v.n)+')</summary><div style="margin-top:8px;display:flex;flex-direction:column;gap:8px">'+exBtn("air-"+v.id)+penTable(v)+'<p class="small"><b>벌칙·과태료</b> '+esc(v.cr)+'</p>'+(v.link?'<a class="linkbtn" href="'+v.link.url+'" target="_blank" rel="noopener">'+esc(v.link.label)+' ↗</a>':'')+'</div></details>':'');
    return itemHtml(it,S.air,{},extra);}).join("");
  $("aItems").innerHTML=html; bindItems($("aItems"),S.air,renderAir); $("aProgress").innerHTML=progressHtml(AITEMS,S.air);
}
$("airName").value=S.air.name;$("airName").addEventListener("input",function(e){S.air.name=e.target.value;persist();});
function renderVio(){
  $("vioList").innerHTML=AIRV.map(function(v){
    var med=MEDIA.filter(function(m){return m.vio&&m.vio.indexOf(v.id)>-1;});
    return '<details class="vio" id="air-'+v.id+'"><summary><b>'+esc(v.n)+'</b>'+(OUTSIDE[v.id]?'<span class="badge b-warn">외부 확인</span>':'<span class="badge b-na">측정·서류</span>')+'</summary><div class="vio-body">'+
      '<div class="basis">'+esc(v.a)+'</div>'+entryActions('air-'+v.id)+exBtn("air-"+v.id)+'<p class="quote">'+esc(v.txt)+'</p>'+(v.cond?'<p class="small"><b>처분 대상</b> '+esc(v.cond)+'</p>':'')+(v.mg?'<p class="small"><b>관리 예시</b> '+esc(v.mg)+'</p>':'')+penTable(v)+'<p class="small"><b>벌칙·과태료</b> '+esc(v.cr)+'</p>'+
      mediaBlock(med)+(v.link?'<a class="linkbtn" href="'+v.link.url+'" target="_blank" rel="noopener">'+esc(v.link.label)+' ↗</a>':'')+'</div></details>';
  }).join("")+'<p class="small muted" style="margin-top:10px">근거 조문·행정처분·벌칙은 대기환경보전법(법률 제21465호) 및 시행규칙 별표 36(2026.7.15 개정) 등의 중요 기준을 2026.10.03 표본 대조했습니다. 전체 조항의 전수 검증을 의미하지 않습니다. 관리 예시는 AI 환경비서 자료를 인용했습니다. ‘측정·서류’ 항목은 사업장 외부에서 확인할 수 없는 사항입니다.</p>';
  bindTiles($("vioList"));
}

