function renderJInputs(){var type=$("jType").value,j=J[type];$("jInputs").innerHTML=j.f.map(function(f,i){return '<div class="field"><label for="jv'+i+'">'+f[0]+' ('+f[1]+')</label><input id="jv'+i+'" type="number" inputmode="decimal" min="0" placeholder="'+f[2].toLocaleString()+' 이상이면 대상"></div>';}).join("");$("jInputs").querySelectorAll("input").forEach(function(i){i.addEventListener("input",judge);});$("jQual").hidden=type!=="farm"&&type!=="paint";$("jCondition").value="";$("jConditionLabel").textContent=type==="farm"?"운송차량으로 토사 반출·반입 또는 농지전용 등을 위한 복합 토공·정지공사인가요?":"장기수선계획을 수립하는 공동주택의 건물 외부 도장인가요?";judge();}
