function hlText(t,ph){
  var out=esc(t); (ph||[]).forEach(function(p){var e=esc(p),i=out.indexOf(e); if(i>-1) out=out.slice(0,i)+'<mark>'+e+'</mark>'+out.slice(i+e.length);});
  var n=0; return out.replace(/<mark>/g,function(){return '<mark style="animation-delay:'+(1.2+0.9*(n++))+'s">';});
}
function d(i,base){return ' style="animation-delay:'+((base||0)+i*0.55).toFixed(2)+'s"';}
/* ---- 자막 분할·음성 ---- */
function chunksOf(t){
  var sent=(t||"").replace(/\s+/g," ").trim().split(/(?<=[다요음]\.)\s+|(?<=\)\.)\s+|(?<=\))\s+(?=[가-힣])/), out=[];
  sent.forEach(function(p){
    if(p.length<=40){ if(p) out.push(p); return; }
    var n=Math.ceil(p.length/38), size=p.length/n, start=0;
    for(var k=1;k<n;k++){ var target=Math.round(k*size), best=-1, bs=1e9;
      for(var j=start+12;j<p.length-8;j++){ if(p[j]!==" ") continue; var sc=Math.abs(j-target)-(p[j-1]===","?6:0)-(/[고며면서]$/.test(p.slice(0,j))?3:0); if(sc<bs){bs=sc;best=j;} }
      if(best<0) break; out.push(p.slice(start,best).trim()); start=best+1; }
    out.push(p.slice(start).trim()); });
  return out.filter(Boolean).length?out.filter(Boolean):[""];
}
function speakText(t){
  return t.replace(/1\/3/g,"삼 분의 일")
   .replace(/(\d+(?:\.\d+)?)\s*㎏\/㎠/g,"제곱센티미터당 $1 킬로그램").replace(/(\d+(?:\.\d+)?)\s*kgf\/㎠/g,"제곱센티미터당 $1 킬로그램힘")
   .replace(/(\d+(?:\.\d+)?)\s*m\/s/g,"초속 $1 미터").replace(/(\d+(?:\.\d+)?)\s*m\b/g,"$1 미터")
   .replace(/㎡/g," 제곱미터").replace(/㎥/g," 세제곱미터").replace(/㎝/g," 센티미터").replace(/㎞/g," 킬로미터")
   .replace(/제(\d+)(조|항|호)/g,"제 $1 $2 ").replace(/→/g,", 다음은 ").replace(/·/g,", ").replace(/\//g,", ")
   .replace(/(\d+)~(\d+)/g,"$1에서 $2").replace(/[():]/g,", ").replace(/\s{2,}/g," ").replace(/^[ ,]+|[ ,]+$/g,"");
}
var VOICE={on:true,mode:"rec",v:null,ok:("speechSynthesis" in window)}, AU=new Audio(); AU.preload="none";
function stopVoice(){ try{AU.onended=null;AU.pause();}catch(e){} if(VOICE.ok) speechSynthesis.cancel(); }
function pickVoice(){ if(!VOICE.ok) return; var vs=speechSynthesis.getVoices().filter(function(v){return /^ko/i.test(v.lang);});
  if(!vs.length) return; var pref=[/natural/i,/sunhi|injoon|hyunsu|seoyeon/i,/yuna|유나|siri/i,/google/i,/premium|enhanced/i];
  for(var i=0;i<pref.length;i++){ var f=vs.filter(function(v){return pref[i].test(v.name);}); if(f.length){VOICE.v=f[0];return;} }
  VOICE.v=vs[0]; }
if(VOICE.ok){ pickVoice(); speechSynthesis.onvoiceschanged=function(){pickVoice(); if(!$("xp").hidden) xpPlayIcon();}; }
try{ var vp=localStorage.getItem("ms.voice"); if(vp==="off"){VOICE.on=false;VOICE.mode="off";} else if(vp==="dev") VOICE.mode="dev"; }catch(e){}
function chunkDur(t){ return Math.max(2600, t.length*150); }
function setSub(t){ var el=$("xpSub"); if(el){ el.textContent=t; el.hidden=!t; } }
/* ---- 재생 엔진 ---- */
function shotEst(sc){ return 900+chunksOf(sc.sub).reduce(function(a,c){return a+chunkDur(c);},0); }
function xpShow(i){
  var ex=XP.ex; XP.i=Math.max(0,Math.min(ex.shots.length-1,i)); XP.ended=false;
  var sc=ex.shots[XP.i];
  stopVoice();
  $("xpStage").innerHTML='<div class="vwrap">'+sc.svg+'<div class="vsubov"><span id="xpSub"></span></div></div>';
  $("xpCap").innerHTML='<span class="vref">'+esc(sc.ref||"")+'</span>';
  $("xpN").textContent=(XP.i+1)+" / "+ex.shots.length;
  var bars=$("xpBars").children; for(var k=0;k<bars.length;k++){bars[k].className=k<XP.i?"done":"";bars[k].firstChild.style.width=k<XP.i?"100%":"0";}
  XP.chunks=chunksOf(sc.sub); XP.ci=-1; XP.dur=shotEst(sc); XP.el=0; XP.t0=performance.now(); XP.tok=(XP.tok||0)+1; XP.chEnd=0;
  var sv=$("xpStage").querySelector("svg"); if(sv&&!XP.play&&sv.pauseAnimations) sv.pauseAnimations();
  xpPlayIcon();
  if(XP.play) xpNextChunk();
  else { XP.ci=0; setSub(XP.chunks[0]); }
}
function xpNextChunk(){
  XP.ci++; var tok=XP.tok;
  if(XP.ci>=XP.chunks.length){ XP.chEnd=performance.now()+700; XP.waitEnd=true; return; }
  XP.waitEnd=false; var t=XP.chunks[XP.ci]; setSub(t);
  if(VOICE.mode==="rec"&&AUD[t]){
    var fin=false; function nx(){ if(fin||tok!==XP.tok||!XP.play) return; fin=true; setTimeout(function(){ if(tok===XP.tok&&XP.play) xpNextChunk(); },220); }
    XP.timerChunk=false; XP.chEnd=performance.now()+chunkDur(t)*2.2+2500;
    AU.onended=nx; AU.src=AUD[t];
    var pr=AU.play(); if(pr&&pr.catch) pr.catch(function(){ if(tok!==XP.tok) return; XP.timerChunk=true; XP.chEnd=performance.now()+chunkDur(t);toast("음성을 불러오지 못했습니다. 연결 또는 음성 자료 저장 상태를 확인하세요."); });
  } else if(VOICE.mode==="dev"&&VOICE.ok&&VOICE.v){
    var u=new SpeechSynthesisUtterance(speakText(t)); u.lang="ko-KR"; u.voice=VOICE.v; u.rate=0.97; u.pitch=1;
    var done=false; function next(){ if(done||tok!==XP.tok||!XP.play) return; done=true; setTimeout(function(){ if(tok===XP.tok&&XP.play) xpNextChunk(); },250); }
    u.onend=next; u.onerror=function(){ XP.chEnd=performance.now()+chunkDur(t); XP.timerChunk=true; };
    XP.timerChunk=false; XP.chEnd=performance.now()+chunkDur(t)*2.2+2000; // 안전장치
    speechSynthesis.speak(u);
  } else { XP.timerChunk=true; XP.chEnd=performance.now()+chunkDur(t); }
}
function xpPlayIcon(){var b=$("xpPlay");b.innerHTML=XP.ended?ICR:(XP.play?ICZ:ICP);b.setAttribute("aria-label",XP.ended?"처음부터":(XP.play?"일시정지":"재생"));$("xp").classList.toggle("paused",!XP.play);
  var vb=$("xpVoice"); if(vb){ var on=VOICE.mode!=="off"; vb.setAttribute("aria-pressed",on); vb.disabled=false; vb.hidden=false;
    vb.innerHTML=(on?ICV1:ICV0)+'<span>'+({rec:"한국어 안내",dev:"기기 한국어 음성",off:"음성 꺼짐"}[VOICE.mode])+'</span>'; } }
function xpTick(now){
  if($("xp").hidden) return;
  if(XP.play&&!XP.ended){
    var e=XP.el+(now-XP.t0), f=Math.min(XP.waitEnd?1:0.97,e/XP.dur);
    var bar=$("xpBars").children[XP.i]; if(bar) bar.firstChild.style.width=(f*100)+"%";
    if(now>=XP.chEnd&&XP.chEnd){ if(XP.waitEnd){ XP.chEnd=0; if(XP.i<XP.ex.shots.length-1) xpShow(XP.i+1); else {XP.ended=true;XP.play=false;setSub("");xpPlayIcon();} }
      else { if(!XP.timerChunk) stopVoice(); xpNextChunk(); } }
  }
  XP.raf=requestAnimationFrame(xpTick);
}
function xpOpen(id){
  var ex=EX[id]; if(!ex) return; XP.ex=ex; XP.play=true;
  $("xpT").textContent=ex.title; $("xpS").textContent=ex.sub;
  $("xpBars").innerHTML=ex.shots.map(function(){return '<i><b></b></i>';}).join("");
  modalOpen("xp","xpClose");
  if(VOICE.ok&&!VOICE.v) pickVoice();
  xpShow(0); cancelAnimationFrame(XP.raf); XP.raf=requestAnimationFrame(xpTick);
}
function xpClose(){modalClose("xp");cancelAnimationFrame(XP.raf);XP.tok++;stopVoice();}
function xpToggle(){
  if(XP.ended){XP.play=true;xpShow(0);return;}
  var sv=$("xpStage").querySelector("svg");
  if(XP.play){ XP.el+=performance.now()-XP.t0; XP.play=false; XP.tok++; stopVoice(); if(sv&&sv.pauseAnimations)sv.pauseAnimations(); }
  else { XP.t0=performance.now(); XP.play=true; if(sv&&sv.unpauseAnimations)sv.unpauseAnimations(); XP.ci=Math.max(-1,XP.ci-1); XP.waitEnd=false; xpNextChunk(); }
  xpPlayIcon();
}
